#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Adaptive Peer Discovery for A2A Mesh.

Replaces fixed 30s peer discovery interval with adaptive scheduling:
  - Idle network: 2-5 minutes (exponential backoff within range)
  - Active traffic: 30s (immediate fallback)

Traffic is measured by counting messages/heartbeats observed since last
discovery cycle. The interval adapts automatically based on network activity.

Run standalone to see a simulation, or import AdaptivePeerDiscovery into the
existing mesh runtime.
"""

import asyncio
import logging
import random
import time
from dataclasses import dataclass, field
from typing import Awaitable, Callable, Optional

logger = logging.getLogger("a2a_mesh.adaptive_discovery")

# ---------------------------------------------------------------------------
# Configuration constants
# ---------------------------------------------------------------------------

MIN_INTERVAL_IDLE = 120.0       # 2 minutes — idle floor
MAX_INTERVAL_IDLE = 300.0       # 5 minutes — idle ceiling
ACTIVE_INTERVAL = 30.0          # 30 seconds — when traffic detected
TRAFFIC_THRESHOLD = 2           # messages since last cycle to count as "active"
BACKOFF_FACTOR = 1.4            # multiplicative growth toward MAX_INTERVAL_IDLE
RECOVERY_FACTOR = 0.6           # shrink back toward MIN_INTERVAL_IDLE on light traffic
JITTER_RATIO = 0.1              # ±10% random jitter to avoid synchronization


# ---------------------------------------------------------------------------
# Data structures
# ---------------------------------------------------------------------------

@dataclass
class DiscoveryState:
    """Tracks runtime state for adaptive discovery scheduling."""
    current_interval: float = ACTIVE_INTERVAL
    traffic_count: int = 0
    last_cycle_ts: float = field(default_factory=time.monotonic)
    total_cycles: int = 0
    idle_cycles: int = 0
    active_cycles: int = 0

    def reset_traffic(self) -> None:
        self.traffic_count = 0

    def record_traffic(self, amount: int = 1) -> None:
        self.traffic_count += amount

    @property
    def is_active(self) -> bool:
        return self.traffic_count >= TRAFFIC_THRESHOLD


# ---------------------------------------------------------------------------
# Core adaptive logic
# ---------------------------------------------------------------------------

class AdaptivePeerDiscovery:
    """
    Adaptive peer discovery scheduler.

    Usage in the mesh runtime:

        discovery = AdaptivePeerDiscovery(discover_fn=mesh.discover_peers)
        discovery.record_traffic()   # call whenever a message/heartbeat arrives
        await discovery.start()      # runs until cancelled

    The discover_fn is an awaitable that performs the actual peer discovery
    (mDNS broadcast, DHT lookup, peer-list exchange, etc.).
    """

    def __init__(
        self,
        discover_fn: Callable[[], Awaitable[None]],
        *,
        min_idle: float = MIN_INTERVAL_IDLE,
        max_idle: float = MAX_INTERVAL_IDLE,
        active: float = ACTIVE_INTERVAL,
        threshold: int = TRAFFIC_THRESHOLD,
        backoff: float = BACKOFF_FACTOR,
        recovery: float = RECOVERY_FACTOR,
        jitter: float = JITTER_RATIO,
    ) -> None:
        self.discover_fn = discover_fn
        self.min_idle = min_idle
        self.max_idle = max_idle
        self.active = active
        self.threshold = threshold
        self.backoff = backoff
        self.recovery = recovery
        self.jitter = jitter
        self.state = DiscoveryState(current_interval=active)
        self._task: Optional[asyncio.Task] = None
        self._running = False

    # -- public API --------------------------------------------------------

    def record_traffic(self, amount: int = 1) -> None:
        """Call whenever mesh traffic (message, heartbeat, relay) is observed."""
        self.state.record_traffic(amount)

    def get_current_interval(self) -> float:
        return self.state.current_interval

    def get_stats(self) -> dict:
        return {
            "current_interval": round(self.state.current_interval, 1),
            "traffic_count": self.state.traffic_count,
            "is_active": self.state.is_active,
            "total_cycles": self.state.total_cycles,
            "idle_cycles": self.state.idle_cycles,
            "active_cycles": self.state.active_cycles,
        }

    async def start(self) -> None:
        """Run the discovery loop until stop() is called or task is cancelled."""
        self._running = True
        logger.info("Adaptive peer discovery started (initial interval: %.1fs)",
                    self.state.current_interval)
        while self._running:
            try:
                await self._cycle()
            except asyncio.CancelledError:
                break
            except Exception:
                logger.exception("Discovery cycle error; continuing")
            await self._sleep_until_next()

    async def stop(self) -> None:
        self._running = False
        if self._task and not self._task.done():
            self._task.cancel()
            try:
                await self._task
            except asyncio.CancelledError:
                pass
        logger.info("Adaptive peer discovery stopped. Stats: %s", self.get_stats())

    def start_as_task(self) -> asyncio.Task:
        """Convenience: schedule the loop as a background task."""
        self._task = asyncio.create_task(self.start())
        return self._task

    # -- internal ----------------------------------------------------------

    async def _cycle(self) -> None:
        """Execute one discovery cycle and update the interval."""
        was_active = self.state.is_active
        await self.discover_fn()
        self.state.total_cycles += 1
        self.state.last_cycle_ts = time.monotonic()

        if was_active:
            self.state.active_cycles += 1
            self.state.idle_cycles = 0
            self.state.current_interval = self.active
        else:
            self.state.idle_cycles += 1
            self.state.active_cycles = 0
            self._grow_idle_interval()

        self.state.reset_traffic()
        logger.debug("Discovery cycle %d complete — next interval: %.1fs (active=%s)",
                     self.state.total_cycles,
                     self.state.current_interval,
                     was_active)

    def _grow_idle_interval(self) -> None:
        """Exponential backoff within [min_idle, max_idle] on consecutive idle cycles."""
        new_interval = self.state.current_interval * self.backoff
        # If we had some traffic but below threshold, recover slightly
        if self.state.traffic_count > 0:
            new_interval = self.state.current_interval * self.recovery
        new_interval = max(self.min_idle, min(self.max_idle, new_interval))
        self.state.current_interval = new_interval

    async def _sleep_until_next(self) -> None:
        """Sleep for current_interval with jitter, but wake early on traffic spike."""
        base = self.state.current_interval
        jitter_amt = base * self.jitter
        sleep_time = base + random.uniform(-jitter_amt, jitter_amt)
        sleep_time = max(1.0, sleep_time)

        # Wake early if traffic arrives (poll every 2s)
        elapsed = 0.0
        poll = 2.0
        while elapsed < sleep_time and self._running:
            step = min(poll, sleep_time - elapsed)
            await asyncio.sleep(step)
            elapsed += step
            # If traffic spikes during idle wait, cut the wait short
            if self.state.traffic_count >= self.threshold and self.state.current_interval > self.active:
                logger.debug("Traffic spike during idle wait — shortening interval")
                self.state.current_interval = self.active
                break


# ---------------------------------------------------------------------------
# Integration helper: drop-in replacement for a fixed-interval loop
# ---------------------------------------------------------------------------

async def run_adaptive_discovery(
    discover_fn: Callable[[], Awaitable[None]],
    traffic_signal: Optional[asyncio.Event] = None,
) -> None:
    """
    Drop-in async replacement for:

        while True:
            await discover_fn()
            await asyncio.sleep(30)

    If traffic_signal is provided, set it whenever mesh traffic occurs;
    the discovery loop will also poll an internal counter.
    """
    discovery = AdaptivePeerDiscovery(discover_fn)

    async def _signal_watcher():
        if traffic_signal is None:
            return
        while True:
            await traffic_signal.wait()
            traffic_signal.clear()
            discovery.record_traffic()

    watcher = asyncio.create_task(_signal_watcher())
    try:
        await discovery.start()
    finally:
        watcher.cancel()
        try:
            await watcher
        except asyncio.CancelledError:
            pass


# ---------------------------------------------------------------------------
# Standalone simulation / self-test
# ---------------------------------------------------------------------------

async def _simulated_discover() -> None:
    """Simulated discovery — in real mesh this does mDNS/DHT/peer exchange."""
    logger.info("[discover] Scanning for peers ...")


async def _simulate_traffic(discovery: AdaptivePeerDiscovery, duration: float) -> None:
    """Simulate random traffic for *duration* seconds."""
    end = time.monotonic() + duration
    while time.monotonic() < end:
        await asyncio.sleep(random.uniform(0.5, 3.0))
        discovery.record_traffic(random.randint(1, 3))


async def main() -> None:
    """
    Simulation:
      Phase 1 (0-15s):  Active traffic  → interval stays at 30s
      Phase 2 (15-45s): Idle            → interval grows 30→120→168→235→300
      Phase 3 (45-55s): Traffic resumes → interval snaps back to 30s
    """
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(levelname)s] %(message)s",
        datefmt="%H:%M:%S",
    )

    discovery = AdaptivePeerDiscovery(_simulated_discover)
    task = discovery.start_as_task()

    # Phase 1: active traffic
    logger.info("=== Phase 1: Active traffic (15s) ===")
    await _simulate_traffic(discovery, 15.0)

    # Phase 2: idle
    logger.info("=== Phase 2: Idle network (30s) — interval should grow ===")
    await asyncio.sleep(30.0)

    # Phase 3: traffic resumes
    logger.info("=== Phase 3: Traffic resumes (10s) — interval should snap to 30s ===")
    await _simulate_traffic(discovery, 10.0)

    # Let one more cycle fire
    await asyncio.sleep(5.0)

    logger.info("=== Final stats: %s ===", discovery.get_stats())
    await discovery.stop()
    task.cancel()
    try:
        await task
    except asyncio.CancelledError:
        pass


if __name__ == "__main__":
    asyncio.run(main())